{"cards": [{"node_code": "N_6deb94418680641b", "definition": "研究制造系统中人工成本、工时消耗及制造间接费用的构成、核算方法与分配机制，旨在准确归集与分摊生产过程中的非直接材料成本。", "boundary": "聚焦于“人”与“非直接物”的成本属性，包括直接/间接人工工资、福利、加班费，以及设备折旧、能源、厂房租金等制造费用（Overhead）的归集与分摊。边界在于关注成本数据的财务属性与核算逻辑，不涉及工时测定的具体动作分析方法（归入工作研究），也不涉及库存持有成本或整体产能利用率指标。", "includes": ["直接人工与间接人工的成本核算、工资率分析及劳动力成本结构", "制造费用（Overhead）的归集、分配基础（如机器小时、人工小时）及分摊方法", "工时成本转化、加班成本分析及人工效率对成本的影响评估"], "excludes": ["基于动作分析或时间研究的工时定额制定方法", "库存持有成本、资金占用成本或供应链物流成本", "纯财务会计准则、税务筹划或企业整体薪酬战略设计"], "sibling_distinctions": [{"other_code": "N_ce9253b893f8dea7", "rule": "本节点关注人工与间接费用的具体构成与核算；兄弟节点关注整体成本要素结构、估算模型及方案经济性比较。"}, {"other_code": "N_8b5fb40ce2357b6e", "rule": "本节点关注人工与间接费用的成本属性；兄弟节点关注库存资金占用、收益回报及综合运营绩效指标。"}, {"other_code": "N_f8f206a99fbb062f", "rule": "本节点关注人工成本投入；兄弟节点关注产出效率、产能利用率及生产率比率指标。"}], "cross_boundary_rule": "涉及人工成本的研究，若侧重工资核算、费用分摊及成本归集，主挂载本节点；若侧重通过动作分析优化工时标准，主挂载“工作研究、动作时间与作业测定”；若侧重人工效率对整体OEE的影响，主挂载“生产率、产能与效率指标”。"}, {"node_code": "N_8b5fb40ce2357b6e", "definition": "研究制造运营中库存资金占用、收益回报及综合运营绩效指标（KPI）的构建与应用，旨在通过量化评估优化资金效率与整体运营效益。", "boundary": "聚焦于库存的经济性影响（如持有成本、缺货成本）及反映运营健康度的综合指标（如ROI、ROA、OEE、准时交付率）。边界在于关注资金效率与绩效评估体系，不涉及库存补货算法或物流运作流程（归入制造物流与库存），也不涉及具体的成本核算方法（归入成本要素或劳动力成本）。", "includes": ["库存持有成本、资金周转率、库存价值评估及库存对现金流的影响", "投资回报率（ROI）、资产回报率（ROA）及制造部门收益分析", "综合运营绩效指标（KPI）体系构建、平衡计分卡在制造中的应用及绩效仪表盘"], "excludes": ["库存控制策略、安全库存计算或补货模型算法", "具体的机械加工工艺改进或设备维护成本核算", "纯企业财务战略、资本结构优化或宏观经济学分析"], "sibling_distinctions": [{"other_code": "N_6deb94418680641b", "rule": "本节点关注库存资金效率与综合绩效；兄弟节点关注人工与间接费用的具体成本构成与核算。"}, {"other_code": "N_ce9253b893f8dea7", "rule": "本节点关注运营结果指标（收益、绩效）；兄弟节点关注成本投入的估算与经济性分析。"}, {"other_code": "N_f8f206a99fbb062f", "rule": "本节点关注综合绩效与收益指标；兄弟节点关注具体的生产率比率、产能利用率及效率指标。"}], "cross_boundary_rule": "涉及库存的研究，若侧重库存成本对利润和资金效率的影响，主挂载本节点；若侧重库存水平优化算法或物流调度，主挂载“制造物流与库存”；若侧重库存持有成本的具体计算，可关联本节点但主挂载视侧重点而定。"}, {"node_code": "N_ce9253b893f8dea7", "definition": "研究制造产品或工艺的成本要素构成、成本估算方法（如参数法、类比法）及不同技术方案的经济性比较分析，旨在支持制造决策与报价。", "boundary": "聚焦于成本的结构分解、预测模型及方案比选，包括直接材料、直接人工、制造费用的综合估算，以及全生命周期成本（LCC）分析。边界在于关注成本估算技术与经济性评价方法，不涉及具体的会计记账流程或纯财务制度，也不涉及具体的工时测定动作分析。", "includes": ["成本要素分解（材料、人工、费用）及成本驱动因素分析", "制造成本估算方法（参数估算、类比估算、学习曲线）及报价策略", "方案经济性比较、全生命周期成本（LCC）分析及投资可行性评估"], "excludes": ["具体的工时定额测定方法或动作分析技术", "库存持有成本或资金周转率等运营绩效指标", "纯财务会计准则、税务筹划或企业整体战略管理"], "sibling_distinctions": [{"other_code": "N_6deb94418680641b", "rule": "本节点关注整体成本估算模型与经济性比较；兄弟节点关注人工与间接费用的具体核算与分摊。"}, {"other_code": "N_8b5fb40ce2357b6e", "rule": "本节点关注成本投入的估算与方案比选；兄弟节点关注运营后的收益回报与综合绩效指标。"}, {"other_code": "N_f8f206a99fbb062f", "rule": "本节点关注成本效率的经济性分析；兄弟节点关注物理产出与投入的比率指标（如生产率、OEE）。"}], "cross_boundary_rule": "涉及成本分析的研究，若侧重估算方法、模型构建及方案经济性比较，主挂载本节点；若侧重具体人工/间接费用的会计归集，主挂载“劳动力、工时与间接成本”；若侧重成本降低后的绩效提升评估，主挂载“库存、收益与运营绩效指标”。"}]}
